def decode_base64_safely(s: str) -> str:
    s = s.strip()
    try:
        clean = re.sub(r"\s+", "", s)
        missing_padding = len(clean) % 4
        if missing_padding:
            clean += "=" * (4 - missing_padding)
        decoded = base64.b64decode(clean, validate=False).decode("utf-8", errors="ignore")
        if "proxies:" in decoded or "server:" in decoded or "://" in decoded:
            return decoded
    except Exception:
        pass
    return s


async def fetch_source(session: aiohttp.ClientSession, url: str) -> str:
    headers = {
        "User-Agent": "ClashMeta/v1.19.2 (HerciniaCloud/2.0; +https://github.com/Alex234123/hercinia-node-pool)"
    }
    try:
        async with session.get(url, headers=headers, ssl=False, timeout=aiohttp.ClientTimeout(total=20)) as resp:
            if resp.status == 200:
                text = await resp.text(errors="ignore")
                return text
    except Exception as e:
        print(f"[Fetch Error] {url}: {e}")
    return ""


async def fetch_all_sources() -> list:
    all_sources = list(SOURCES)
    # Support dynamic custom sources from sync API if available
    try:
        async with aiohttp.ClientSession() as s:
            async with s.get("https://pool.hercinia.kdns.fr/api/sync", timeout=aiohttp.ClientTimeout(total=5)) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    custom_sources = data.get("sources", [])
                    for cs in custom_sources:
                        if cs and cs not in all_sources:
                            all_sources.append(cs)
    except Exception as e:
        print(f"[Sync] Skip dynamic sync endpoint: {e}")

    async with aiohttp.ClientSession() as session:
        tasks = [fetch_source(session, url) for url in all_sources]
        results = await asyncio.gather(*tasks)
    return [r for r in results if r and len(r) > 100]


def extract_proxies_from_content(content: str) -> list:
    text = decode_base64_safely(content)
    text = re.sub(r"(short-id:\s*)([0-9a-fA-F]+)", r"\1'\2'", text)

    proxies = []
    # 1. Try pyyaml safe_load
    try:
        data = yaml.safe_load(text)
        if isinstance(data, dict) and "proxies" in data and isinstance(data["proxies"], list):
            for p in data["proxies"]:
                if isinstance(p, dict) and "name" in p and "server" in p and "port" in p and "type" in p:
                    proxies.append(p)
            if proxies:
                return proxies
    except Exception:
        pass

    # 2. Resilient Line-by-line block extractor fallback
    lines = text.splitlines()
    in_proxies = False
    cur_block = []

    def parse_block(b_lines):
        block_text = "\n".join(b_lines)
        try:
            parsed = yaml.safe_load(block_text)
            if isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], dict):
                return parsed[0]
            if isinstance(parsed, dict):
                return parsed
        except Exception:
            pass
        item = {}
        for line in b_lines:
            m = re.match(r"^\s*-\s*([^:]+):\s*(.*)$", line)
            if not m:
                m = re.match(r"^\s*([^:]+):\s*(.*)$", line)
            if m:
                k = m.group(1).strip()
                v = m.group(2).strip().strip("'\"")
                if k == "port":
                    try: v = int(v)
                    except: pass
                item[k] = v
        if "server" in item and "port" in item and "type" in item:
            return item
        return None

    for line in lines:
        stripped = line.strip()
        if re.match(r"^proxies:\s*$", stripped):
            in_proxies = True
            continue
        if in_proxies and re.match(r"^(proxy-groups|rules|rule-providers|proxy-providers):\s*$", stripped):
            in_proxies = False
            if cur_block:
                p = parse_block(cur_block)
                if p: proxies.append(p)
                cur_block = []
            break
        if in_proxies:
            if re.match(r"^\s*-\s*", line):
                if cur_block:
                    p = parse_block(cur_block)
                    if p: proxies.append(p)
                    cur_block = []
                cur_block.append(line)
            elif cur_block:
                cur_block.append(line)

    if cur_block:
        p = parse_block(cur_block)
        if p: proxies.append(p)

    return proxies


def sanitize_node(node: dict) -> dict:
    clean = {}
    for k, v in node.items():
        if k == "port":
            try:
                clean["port"] = int(v)
            except Exception:
                return None
        elif isinstance(v, (str, int, float, bool, list, dict)):
            clean[k] = v
    if not clean.get("server") or not clean.get("type") or not clean.get("port"):
        return None
    return clean


def deduplicate_nodes(proxies: list) -> list:
    seen = set()
    unique = []
    for p in proxies:
        if not isinstance(p, dict):
            continue
        clean = sanitize_node(p)
        if not clean:
            continue
        server = str(clean.get("server", "")).strip()
        port = str(clean.get("port", "")).strip()
        ptype = str(clean.get("type", "")).strip().lower()
        if not server or not port or not ptype:
            continue
        if server in ("127.0.0.1", "localhost", "0.0.0.0") or server.startswith("192.168."):
            continue
        secret = str(clean.get("uuid") or clean.get("password") or clean.get("name") or "")
        key = f"{ptype}|{server.lower()}:{port}|{secret}"
        if key not in seen:
            seen.add(key)
            unique.append(clean)
    return unique


async def benchmark_node_tcp(node: dict, sem: asyncio.Semaphore, timeout: float = 2.0):
    async with sem:
        server = str(node.get("server", "")).strip()
        try:
            port = int(node.get("port"))
        except Exception:
            return None

        # Resolve domain and test TCP handshake delay
        t0 = time.perf_counter()
        try:
            reader, writer = await asyncio.wait_for(
                asyncio.open_connection(server, port),
                timeout=timeout
            )
            t1 = time.perf_counter()
            delay_ms = int((t1 - t0) * 1000)
            writer.close()
            try:
                await writer.wait_closed()
            except Exception:
                pass
            if 0 < delay_ms <= 2000:
                return (node, delay_ms)
        except Exception:
            pass
        return None


async def benchmark_node_real_mihomo(client: aiohttp.ClientSession, node_name: str, sem: asyncio.Semaphore, timeout: float = 3.0):
    async with sem:
        test_url = f"http://127.0.0.1:9097/proxies/{urllib.parse.quote(node_name)}/delay?timeout=2500&url=https://www.google.com/generate_204"
        try:
            async with client.get(test_url, timeout=aiohttp.ClientTimeout(total=timeout)) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    delay = data.get("delay", 0)
                    if 0 < delay < 2500:
                        return delay
        except Exception:
            pass
        return None


async def benchmark_all_nodes(nodes: list) -> list:
    print(f"[Benchmark] Bypass filtering: Directly including all {len(nodes)} deduplicated nodes without dropping...")
    # 完全关闭筛选：将所有拉取解析到的节点 100% 全量保留并生成订阅
    all_alive = [(n, 66) for n in nodes]
    print(f"[Benchmark] 100% Passthrough! All {len(all_alive)} candidate nodes preserved for clash.yaml.")
    return all_alive


